import ast, pathlib

files = []
for p in pathlib.Path(".").rglob("*.py"):
    s = str(p)
    if s.startswith(".venv/") or "/node_modules/" in s or s.startswith(".git/"):
        continue
    if "/migrations/versions/" in s:
        continue
    files.append(p)

results = {}
for f in files:
    try:
        src = f.read_text()
        tree = ast.parse(src)
    except Exception as e:
        continue
    long_funcs = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            length = (node.end_lineno - node.lineno + 1)
            if length > 100:
                long_funcs.append((node.name, node.lineno, node.end_lineno, length))
    if long_funcs:
        results[str(f)] = long_funcs

total_funcs = sum(len(v) for v in results.values())
print(f"Files with >100-line functions: {len(results)}")
print(f"Total long functions: {total_funcs}")
print()
for f, funcs in sorted(results.items(), key=lambda kv: -max(x[3] for x in kv[1])):
    for name, start, end, length in sorted(funcs, key=lambda x: -x[3]):
        print(f"{length:5d}  {f}:{start}-{end}  {name}")
EOF

