export const meta = {
  name: 'refactor-long-functions',
  description: 'Find functions >100 lines, propose refactors per file, independently verify each, dedupe, report',
  phases: [
    { title: 'Analyze' },
    { title: 'Dedupe' },
    { title: 'Verify' },
  ],
}

const FILES = args.files

const ANALYZE_SCHEMA = {
  type: 'object',
  properties: {
    file: { type: 'string' },
    functions: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          start_line: { type: 'number' },
          end_line: { type: 'number' },
          length: { type: 'number' },
          refactor_proposal: { type: 'string' },
          rationale: { type: 'string' },
        },
        required: ['name', 'start_line', 'end_line', 'length', 'refactor_proposal', 'rationale'],
      },
    },
  },
  required: ['file', 'functions'],
}

const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    verdict: { type: 'string', enum: ['approve', 'revise', 'reject'] },
    comments: { type: 'string' },
  },
  required: ['verdict', 'comments'],
}

phase('Analyze')
const analyzeResults = await parallel(FILES.map(f => () =>
  agent(
    `Read the Python file ${f.path} in the wakil repo (a local-first Markdown knowledge-base CLI agent; keep proposals boring, local, simple — no speculative abstractions, no new frameworks, per project engineering principle). ` +
    `The following functions in this file are known to exceed 100 lines: ${JSON.stringify(f.functions)}. ` +
    `For EACH of these functions, read its full body at the given line range and propose a concrete refactor to bring it under 100 lines (e.g. extract helper functions, split responsibilities, remove duplication). ` +
    `Do not propose introducing new abstractions or frameworks beyond what's needed to shrink the function. ` +
    `Return one entry per function with a specific refactor_proposal (what to extract/split, named helpers) and a short rationale.`,
    { label: `analyze:${f.path}`, phase: 'Analyze', schema: ANALYZE_SCHEMA }
  ).then(r => ({ ...r, __requested: f.path })).catch(() => null)
))

log(`Analyze phase: ${analyzeResults.filter(Boolean).length}/${FILES.length} files returned proposals`)

phase('Dedupe')
const seen = new Set()
const proposals = []
for (const r of analyzeResults) {
  if (!r) continue
  for (const fn of (r.functions || [])) {
    const key = `${r.file}::${fn.name}::${fn.start_line}`
    if (seen.has(key)) continue
    seen.add(key)
    proposals.push({ file: r.file, ...fn })
  }
}
log(`Dedupe phase: ${proposals.length} unique proposals after dedup (from ${analyzeResults.filter(Boolean).reduce((n, r) => n + (r.functions?.length || 0), 0)} raw)`)

phase('Verify')
const verified = await parallel(proposals.map(p => () =>
  agent(
    `You are an independent reviewer with no prior context on this task. In the wakil repo (a local-first Markdown knowledge-base CLI agent that values simple, boring, explicit code over speculative abstraction), someone proposed this refactor:\n\n` +
    `File: ${p.file}\nFunction: ${p.name} (lines ${p.start_line}-${p.end_line}, ${p.length} lines)\nProposal: ${p.refactor_proposal}\nRationale: ${p.rationale}\n\n` +
    `Read the actual function in the file at that line range and judge the proposal on its merits: is it correct (does it actually reduce length / improve clarity), is it safe (preserves behavior), and is it proportionate (no unneeded abstraction per the project's anti-over-engineering principle)? ` +
    `Return a verdict of approve, revise, or reject, with specific comments.`,
    { label: `verify:${p.file}:${p.name}`, phase: 'Verify', schema: VERIFY_SCHEMA }
  ).then(v => ({ ...p, verdict: v })).catch(() => ({ ...p, verdict: null }))
))

const missingVerify = verified.filter(v => !v.verdict).length
if (missingVerify > 0) log(`WARNING: ${missingVerify} proposals failed verification and have no verdict`)

return {
  files_scanned: FILES.length,
  files_with_proposals: analyzeResults.filter(Boolean).length,
  files_failed: FILES.length - analyzeResults.filter(Boolean).length,
  raw_proposal_count: analyzeResults.filter(Boolean).reduce((n, r) => n + (r.functions?.length || 0), 0),
  deduped_proposal_count: proposals.length,
  verified,
}

